use vstd::prelude::*;

verus! {

    // A small specification function for the absolute difference of two nonnegative i8s,
    // returning a nat.
    spec fn abs_diff(x: i8, y: i8) -> nat {
        if x >= y {
            (x - y) as nat
        } else {
            (y - x) as nat
        }
    }

    // determine_winner returns "Alice" iff |x - y| > 1, and "Brown" otherwise.
    fn determine_winner(x: i8, y: i8) -> (winner: &'static str)
        requires
            x >= 0,
            y >= 0,
        ensures
            (winner == "Alice")  <==> (abs_diff(x, y) > 1),
            (winner == "Brown")  <==> (abs_diff(x, y) <= 1),
    {
        // Compute the signed difference and cast to a nat.
        let diff_signed: i8 = if x >= y { x - y } else { y - x };
        // Since x,y ≥ 0, the result of subtraction is ≥ 0.
        assert(diff_signed >= 0);
        let d: nat = diff_signed as nat;

        // Relate our local computation back to the spec.
        assert(d == abs_diff(x, y));

        if d > 1 {
            // By the assert above, abs_diff(x,y) = d > 1
            assert(abs_diff(x, y) > 1);
            "Alice"
        } else {
            // d ≤ 1  ⇒  abs_diff(x,y) ≤ 1
            assert(abs_diff(x, y) <= 1);
            "Brown"
        }
    }

}

fn main() {
    // examples
    assert!(determine_winner(0, 0) == "Brown");
    assert!(determine_winner(2, 0) == "Alice");
    assert!(determine_winner(5, 4) == "Brown");
    assert!(determine_winner(7, 5) == "Alice");
}